export type CheckboxGroupChangeEventDetails = {
  readonly reason: "none";
  readonly event: Event;
  cancel: () => void;
  allowPropagation: () => void;
  readonly isCanceled: boolean;
  readonly isPropagationAllowed: boolean;
  readonly trigger: Element | undefined;
};

export function createCheckboxGroupChangeEventDetails(
  event: Event = new Event("base-ui"),
): CheckboxGroupChangeEventDetails {
  let canceled = false;
  let propagationAllowed = false;

  return {
    reason: "none",
    event,
    cancel() {
      canceled = true;
    },
    allowPropagation() {
      propagationAllowed = true;
    },
    get isCanceled() {
      return canceled;
    },
    get isPropagationAllowed() {
      return propagationAllowed;
    },
    trigger: undefined,
  };
}

import { createContext } from "svelte";

export type CheckboxGroupContext = {
  readonly allValues: readonly string[];
  readonly disabled: boolean;
  readonly value: readonly string[];
  itemInputId: (value: string) => string;
  prepareChange: (event: Event) => void;
  clearPreparedChange: (event: Event) => void;
  registerItem: (value: string, isDisabled: () => boolean) => () => void;
  toggleParent: () => void;
};

export const [getCheckboxGroupContext, setCheckboxGroupContext] =
  createContext<CheckboxGroupContext>();

export { CheckboxGroup as CheckboxGroupPrimitive } from "@shardsui/svelte";
export type { CheckboxGroupChangeEventDetails } from "./change-event-details.js";
export type { CheckboxGroupItemProps } from "./checkbox-group-item.svelte";
export {
  default as CheckboxGroupItem,
  default as Item,
  default as Parent,
} from "./checkbox-group-item.svelte";
export type { CheckboxGroupRootProps } from "./checkbox-group-root.svelte";
export {
  default as CheckboxGroup,
  default as CheckboxGroupRoot,
  default as Root,
} from "./checkbox-group-root.svelte";
export type { CheckboxGroupContext } from "./context.js";
